import type {
  TopologyDataset,
} from "../topology/TopologyDatasetTransition.ts";

export interface PresentationSlideDefinition {
  id: string;
  title: string;
  subtitle: string;
  summary: string;
  status: string;
  route: string;
  role: string;
  displayMode: "ring" | "linear" | "fishspine";
  anchors: readonly PresentationAnchorDefinition[];
  content?: string;
}

export interface PresentationAnchorDefinition {
  id: string;
  label: string;
  subtitle?: string;
  children: readonly PresentationChildDefinition[];
}

export interface PresentationChildDefinition {
  id: string;
  label: string;
  subtitle?: string;
}

export interface PresentationRecord {
  id: string;
  presetId: string;
  eyebrow: string;
  title: string;
  subtitle: string;
  summary: string;
  status: string;
  route: string;
  role: string;
  content: string;
}

export interface PresentationSlide {
  id: string;
  title: string;
  subtitle: string;
  summary: string;
  status: string;
  route: string;
  role: string;
  displayMode: "ring" | "linear" | "fishspine";
  topology: TopologyDataset;
  records: PresentationRecord[];
}

