const axialRing = [
  { q: 0, r: -2 },
  { q: 2, r: -2 },
  { q: 2, r: 0 },
  { q: 0, r: 2 },
  { q: -2, r: 2 },
  { q: -2, r: 0 },
] as const;

function createLinearSlideTopology(
  definition: PresentationSlideDefinition,
  seed: { anchors: readonly PresentationAnchorDefinition[] },
): TopologyDataset {
  const rootId = `presentation-${definition.id}-root`;
  const rawRoot = {
    id: rootId,
    label: definition.title,
    subtitle: "Root",
    q: 0,
    r: 0,
    variant: "root" as const,
    size: "root" as const,
    active: true,
    selected: true,
  };
  const rawAnchors = seed.anchors.map((anchor, index) => ({
    id: `presentation-${definition.id}-anchor-${anchor.id}`,
    label: anchor.label,
    subtitle: anchor.subtitle ?? "Anchor",
    q: (index + 1) * 3,
    r: 0,
    variant: "anchor" as const,
    size: "lg" as const,
    active: true,
    source: anchor,
  }));
  const rawChildren = rawAnchors.flatMap((anchor) => anchor.source.children.map((child, childIndex) => ({
    id: `presentation-${definition.id}-node-${anchor.source.id}-${child.id}`,
    label: child.label,
    subtitle: child.subtitle ?? "Node",
    q: anchor.q,
    r: (childIndex + 1) * 2,
    variant: "entity" as const,
    size: "md" as const,
    anchorId: anchor.id,
  })));
  const allPositions = [rawRoot, ...rawAnchors, ...rawChildren];
  const qOffset = -Math.round((Math.min(...allPositions.map((node) => node.q)) + Math.max(...allPositions.map((node) => node.q))) / 2);
  const rOffset = -Math.round((Math.min(...allPositions.map((node) => node.r)) + Math.max(...allPositions.map((node) => node.r))) / 2);
  const root = { ...rawRoot, q: rawRoot.q + qOffset, r: rawRoot.r + rOffset };
  const anchors = rawAnchors.map(({ source: _source, ...anchor }) => ({
    ...anchor,
    q: anchor.q + qOffset,
    r: anchor.r + rOffset,
  }));
  const children = rawChildren.map((child) => ({
    ...child,
    q: child.q + qOffset,
    r: child.r + rOffset,
  }));
  const anchorRelationships = anchors.map((anchor, index) => ({
    from: index === 0 ? rootId : anchors[index - 1].id,
    to: anchor.id,
    active: true,
  }));
  const childRelationships = anchors.flatMap((anchor) => {
    const branch = children.filter((child) => child.anchorId === anchor.id);
    return branch.map((child, index) => ({
      from: index === 0 ? anchor.id : branch[index - 1].id,
      to: child.id,
      active: true,
    }));
  });

  return {
    nodes: [root, ...anchors, ...children],
    relationships: [...anchorRelationships, ...childRelationships],
  };
}

function createFishspineSlideTopology(
  definition: PresentationSlideDefinition,
  seed: { anchors: readonly PresentationAnchorDefinition[] },
): TopologyDataset {
  const rootId = `presentation-${definition.id}-root`;
  const rawRoot = {
    id: rootId,
    label: definition.title,
    subtitle: "Root",
    q: 0,
    r: 0,
    variant: "root" as const,
    size: "root" as const,
    active: true,
    selected: true,
  };
  const rawAnchors = seed.anchors.map((anchor, index) => ({
    id: `presentation-${definition.id}-anchor-${anchor.id}`,
    label: anchor.label,
    subtitle: anchor.subtitle ?? "Anchor",
    q: (index + 1) * 2,
    r: 0,
    variant: "anchor" as const,
    size: "lg" as const,
    active: true,
    source: anchor,
  }));
  const rawChildren = rawAnchors.flatMap((anchor, anchorIndex) => anchor.source.children.map((child, childIndex) => ({
    id: `presentation-${definition.id}-node-${anchor.source.id}-${child.id}`,
    label: child.label,
    subtitle: child.subtitle ?? "Node",
    q: anchor.q + (anchorIndex % 2 === 0 ? 0 : (childIndex + 1) * 2),
    r: anchorIndex % 2 === 0 ? 2 : -2,
    variant: "entity" as const,
    size: "md" as const,
    anchorId: anchor.id,
  })));
  const allPositions = [rawRoot, ...rawAnchors, ...rawChildren];
  const qOffset = -Math.round((Math.min(...allPositions.map((node) => node.q)) + Math.max(...allPositions.map((node) => node.q))) / 2);
  const rOffset = -Math.round((Math.min(...allPositions.map((node) => node.r)) + Math.max(...allPositions.map((node) => node.r))) / 2);
  const root = { ...rawRoot, q: rawRoot.q + qOffset, r: rawRoot.r + rOffset };
  const anchors = rawAnchors.map(({ source: _source, ...anchor }) => ({
    ...anchor,
    q: anchor.q + qOffset,
    r: anchor.r + rOffset,
  }));
  const children = rawChildren.map((child) => ({
    ...child,
    q: child.q + qOffset,
    r: child.r + rOffset,
  }));
  const anchorRelationships = anchors.map((anchor, index) => ({
    from: index === 0 ? rootId : anchors[index - 1].id,
    to: anchor.id,
    active: true,
  }));
  const childRelationships = anchors.flatMap((anchor) => {
    const branch = children.filter((child) => child.anchorId === anchor.id);
    return branch.map((child, index) => ({
      from: index === 0 ? anchor.id : branch[index - 1].id,
      to: child.id,
      active: true,
    }));
  });

  return {
    nodes: [root, ...anchors, ...children],
    relationships: [...anchorRelationships, ...childRelationships],
  };
}

function createSlideTopology(definition: PresentationSlideDefinition): TopologyDataset {
  const catalogSeed = PRESENTATION_SLIDE_SEEDS[definition.id] ?? {
    anchors: ["Context", "Relationships", "Content"].map((label, index) => ({
      id: label.toLowerCase(),
      label,
      children: [{ id: `child-${index}`, label: ["Overview", "Related", "Details"][index] }],
    })),
  };
  const seed = definition.anchors.length > 0 ? definition : { ...definition, anchors: catalogSeed.anchors };
  if (definition.displayMode === "linear") {
    return createLinearSlideTopology(definition, seed);
  }
  if (definition.displayMode === "fishspine") {
    return createFishspineSlideTopology(definition, seed);
  }
  const rootId = `presentation-${definition.id}-root`;
  const root = {
    id: rootId,
    label: definition.title,
    subtitle: "Root",
    q: 0,
    r: 0,
    variant: "root" as const,
    size: "root" as const,
    active: true,
    selected: true,
  };
  const anchors = seed.anchors.map((anchor, index) => {
    const position = axialRing[index % axialRing.length];
    return {
      id: `presentation-${definition.id}-anchor-${anchor.id}`,
      label: anchor.label,
      subtitle: anchor.subtitle ?? "Anchor",
      q: position.q,
      r: position.r,
      variant: "anchor" as const,
      size: "lg" as const,
      active: true,
    };
  });
  const children = seed.anchors.flatMap((anchor, anchorIndex) => {
    const position = axialRing[anchorIndex % axialRing.length];
    return anchor.children.map((child, childIndex) => ({
      id: `presentation-${definition.id}-node-${anchor.id}-${child.id}`,
      label: child.label,
      subtitle: child.subtitle ?? "Node",
      q: position.q + Math.sign(position.q) * (childIndex + 1),
      r: position.r + Math.sign(position.r) * (childIndex + 1),
      variant: "entity" as const,
      size: "md" as const,
      anchorId: `presentation-${definition.id}-anchor-${anchor.id}`,
    }));
  });

  return {
    nodes: [root, ...anchors, ...children],
    relationships: anchors.flatMap((anchor) => [
      { from: rootId, to: anchor.id, active: true },
      ...children
        .filter((child) => child.anchorId === anchor.id)
        .map((child) => ({ from: anchor.id, to: child.id, active: true })),
    ]),
  };
}

function normalizeContentMatch(value: string): string {
  return value
    .toLocaleLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
}

function getNodeContent(content: string, label: string, isRoot: boolean): string {
  const source = content.trim();
  if (!source || isRoot) return source;

  const decodeEntities = (value: string) => value
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"');
  const stripTags = (value: string) => decodeEntities(value.replace(/<[^>]+>/g, " "));
  const target = normalizeContentMatch(label);
  const headingPattern = /<h([1-6])(?:\s[^>]*)?>([\s\S]*?)<\/h\1>/gi;
  const headings = [...source.matchAll(headingPattern)];
  const startHeading = headings.find((heading) =>
    normalizeContentMatch(stripTags(heading[2])).includes(target),
  );

  if (!startHeading || startHeading.index === undefined) return source;

  const level = Number(startHeading[1]);
  const endHeading = headings.find((heading) =>
    heading.index !== undefined &&
    heading.index > startHeading.index &&
    Number(heading[1]) <= level,
  );
  const end = endHeading?.index ?? source.length;
  return source.slice(startHeading.index, end).trim();
}

export function createPresentationSlides(
  definitions: readonly PresentationSlideDefinition[],
): PresentationSlide[] {
  return definitions.map((definition) => {
    const topology = createSlideTopology(definition);
    const records: PresentationRecord[] = topology.nodes.map((node) => ({
      id: node.id,
      presetId: definition.id,
      eyebrow: definition.title,
      title: node.label,
      subtitle: node.subtitle ?? "Topology node",
      summary: node.variant === "root"
        ? definition.summary
        : node.variant === "anchor"
          ? `${node.label} organizes a related branch of this presentation.`
          : `${node.label} is a child node in the ${definition.title} presentation.`,
      status: node.variant === "root" ? definition.status : "ready",
      route: definition.route,
      role: node.variant === "root" ? "root" : node.variant === "anchor" ? "anchor" : "node",
      content: getNodeContent(
        definition.content ?? "",
        node.label,
        node.variant === "root",
      ),
    }));

    return {
      ...definition,
      topology,
      records,
    };
  });
}
